package vn.covie.outbox.application; import java.util.List; import org.springframework.stereotype.Component; @Component public class OutboxHandlerRegistry {private final List<OutboxEventHandler> handlers;public OutboxHandlerRegistry(List<OutboxEventHandler> handlers){this.handlers=List.copyOf(handlers);}public List<OutboxEventHandler> handlersFor(String type){return handlers.stream().filter(h->h.supports(type)).toList();}}
